/// <summary>
///    Indicates whether the specified record in the <c>AVAsmmContactTitleGroupTranslation</c> table exists.
/// </summary>
/// <param name="_recId">
///    The record ID of the record to check for existence.
/// </param>
/// <returns>
///    true if the specified record exists; otherwise, false.
/// </returns>
public static boolean exist(RefRecId _recId)
{
    return (AVADirNameAffixTranslation::find(_recId).RecId != 0);
}

/// <summary>
///     Find the specified record in the <c>AVADirNameAffixTranslation</c> table.
/// </summary>
/// <param name="_recId">
///     The record ID of the record to find.
/// </param>
/// <param name="_forupdate">
///     A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///     A record in the <c>AVADirNameAffixTranslation</c> table; otherwise, an empty buffer.
/// </returns>
public static AVADirNameAffixTranslation find(  RefRecId    _recId,
                                                boolean     _forupdate = false)
{
    AVADirNameAffixTranslation record;

    if (!_recId)
    {
        return record;
    }
    record.selectForUpdate(_forupdate);
    select firstonly record 
    where record.RecId == _recId;

    return record;
}

/// <summary>
///     Finds all of the translated languages for a specified attribute.
/// </summary>
/// <param name="_refRecId">
///     The record ID of the related <c>DirNameAffix</c> record.
/// </param>
/// <returns>
///     A container of the translated languages.
/// </returns>
public static container findAllTranslatedLanguages(RefRecId _refRecId)
{
    AVADirNameAffixTranslation  locAVADirNameAffixTranslation;
    List                        list;

    list = new List(Types::String);

    while select Language
    from    locAVADirNameAffixTranslation
    where   locAVADirNameAffixTranslation.DirNameAffixRefRecId == _refRecId
    {
        list.addEnd(locAVADirNameAffixTranslation.Language);
    }

    return list.pack();
}

/// <summary>
///     Finds the specified record in the <c>AVADirNameAffixTranslation</c> table by using the related
///     attribute and language ID.
/// </summary>
/// <param name="_refRecId">
///     The record ID of the related <c>DirNameAffix</c> record.
/// </param>
/// <param name="_languageId">
///     The language ID of the record to find.
/// </param>
/// <param name="_forupdate">
///     A Boolean value that indicates whether the record is selected for update; optional.
/// </param>
/// <returns>
///     A record in the <c>AVADirNameAffixTranslation</c> table; otherwise, an empty record buffer.
/// </returns>
public static AVADirNameAffixTranslation findByDirNameAffixAndLanguage( RefRecId    _refRecId,
                                                                        LanguageId  _languageId,
                                                                        boolean     _forupdate = false)
{
    AVADirNameAffixTranslation record;

    record.selectForUpdate(_forupdate);

    select firstonly record
    where   record.DirNameAffixRefRecId == _refRecId
        &&  record.Language             == _languageId;

    return record;
}
